curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 20, filter: { title: { contains: \"Renew SSO certificate\" } }) { nodes { id title url priority assignee { name email } creator { name email } } } }"
  }'
